/* =======================================================

13 pairs of cubes

Select 2 cubes by clicking on them, then press <Space>.
If they are the same they will be removed.

Drag mouse on background to rotate the world.
Press <R> to Reset.

Try different textures or videos...

========================================================= */

vec3 jetColorMap(float t) { // 0 ... 1
    return clamp(vec3(1.5) - abs(4.0 * vec3(t) + vec3(-3., -2., -1.)), vec3(0.), vec3(1.));
}

void mainImage(out vec4 O, vec2 U) {
    R = iResolution.xy;
    uv = U.xy / R;

    O.xyz = vec3(0.,0.4,0.5); 
    loadData(iChannel0);

    // -----------------------------------------
    // sort cubes by distance for painter's algorithm
    ivec2 dist[NUMCUBE];
    for(int i=0;i<NUMCUBE;++i) {
        dist[i].x = i;  // cube indice
        dist[i].y = int(finalPosition(i,(i == int(qHighlight1) || i == int(qHighlight2)))); // distance from camera
    }

    int sanity = 0;
    while(true) { // bubble sort by distance
        bool okay = true;
        for(int i=0;i<NUMCUBE-1;++i) {
            if(dist[i].y > dist[i+1].y) {
                ivec2 t = dist[i];
                dist[i] = dist[i+1];
                dist[i+1] = t;
                okay = false;
            }
        }
        if(okay || ++sanity > 100) break;
    }

    // -----------------------------------------
    CubeData t;
    t.size = iResolution.x * 0.06;
    t.range = 0.;
    t.rot = vec3(iTime*0.5, iTime*0.35, 0.);
    t.drawEdge = true;
    t.edgeColor = vec3(0.);
    t.edgeWidth = 1.;
    for(int i=0;i<6;++i)
        t.face[i].kind = 1;

    int cubeIndex,regionIndex;

    for(int i=0;i<NUMCUBE;++i) {
        cubeIndex = dist[i].x;

        regionIndex = getCubeEntry(cubeIndex);
        if(regionIndex == EMPTY) continue;

        t.face[0].kind = FACE_SOLID;
        t.face[0].color = jetColorMap(float(regionIndex)/ float(NUMREGION));
        for(int j=1;j<3;++j) t.face[j].kind = FACE_TEXTURE1;
        for(int j=3;j<6;++j) t.face[j].kind = FACE_TEXTURE2;

        for(int j=1;j<6;++j) {            
            float rv = regionSize[regionIndex];

            t.face[j].uv = vec2(sin(iTime * rv * 0.1) / rv);
            t.face[j].sz = rv;

            regionIndex = (regionIndex + 3) % NUMREGION;
        }

        t.pos = positions[cubeIndex];        
        t.edgeColor = vec3(0.);
        t.edgeWidth = 1.;

        t.isHighlighted = cubeIndex == int(qHighlight1) || cubeIndex == int(qHighlight2);
        if(t.isHighlighted) {
            t.edgeColor = vec3(1.,0.,0.);
            t.edgeWidth = 2.;
        }

        cube(t,O,U,iChannel1,iChannel2);
    }
}

//=============================================================
// game related
//=============================================================

const int NUMCUBE = 26;  // 3x3x3-1
const int NUMREGION = NUMCUBE/2;
const int EMPTY = -1;
#define FEMPTY float(EMPTY)

#define qWorld      q[0].xy // world rotation
#define qHighlight1 q[0].z  // indices of selected cubes
#define qHighlight2 q[0].w

const int CBASE  = 1;  // beginning to cube status entries
const int CDATA  = 7;  // #cube status entries (4 per vec4). EMPTY = cube is removed, else regionIndex
const int QSIZE  = 8;  // total storage

vec4 q[QSIZE];

void loadData(sampler2D channel) {
    for(int i=0;i<QSIZE;++i) 
        q[i] = texelFetch(channel,ivec2(i,0),0);
}

void saveData(inout vec4 O,vec2 U) {
    ivec2 I = ivec2(U);    
    if(I.y == 0 && I.x < QSIZE) 
        O = vec4(q[I.x]);
}

int getCubeEntry(int cIndex) { return int(q[CBASE + int(cIndex / 4)][cIndex % 4]); }
void  setCubeEntry(int cIndex,int value) { q[CBASE + int(cIndex / 4)][cIndex % 4] = float(value); }

// ----------------------------------
vec2 R,uv;
float cubeSize;

#define A -2.7
#define B 0.
#define C -A
const vec3[] positions = vec3[](
    vec3(A,A,A),vec3(B,A,A),vec3(C,A,A),vec3(A,B,A),vec3(B,B,A),vec3(C,B,A),vec3(A,C,A),vec3(B,C,A),vec3(C,C,A),
    vec3(A,A,B),vec3(B,A,B),vec3(C,A,B),vec3(A,B,B),            vec3(C,B,B),vec3(A,C,B),vec3(B,C,B),vec3(C,C,B),
    vec3(A,A,C),vec3(B,A,C),vec3(C,A,C),vec3(A,B,C),vec3(B,B,C),vec3(C,B,C),vec3(A,C,C),vec3(B,C,C),vec3(C,C,C));

#define NUMREGION 13    
const float regionSize[NUMREGION] = float[](0.02,0.03,0.04,0.4,0.18,0.1,0.15,0.2,0.25,0.3,0.35,0.4,0.45);    

const vec3 camera = vec3(0.,0.,10.);

mat2 rotate(float angle) {
    float s = sin(angle),c = cos(angle);
    return mat2(c,-s,s,c);
}

void rotateWorld(inout vec3 pos) {
    pos.xy *= rotate(qWorld.x);    
    pos.yz *= rotate(qWorld.y);    
}

vec3 finalPosition(int cubeIndex, bool isHighlighted) {
    vec3 pos = positions[cubeIndex];
    rotateWorld(pos);  
    if(isHighlighted) pos *= 1.5;

    pos *= cubeSize * 0.75;
    pos.xy = R.xy * 0.5 - pos.xy;                
    return pos;
}

float cubeDistance(int cubeIndex, bool isHighlighted) {
    vec3 vert = finalPosition(cubeIndex,isHighlighted);
    return distance(vert, camera);
}

// ----------------------------------------------------------

bool keyClick(int ascii,sampler2D channel) {
    return (texture(channel,vec2((.5+float(ascii))/256.,0.25)).x > 0.);
}

bool getKeyState(int keyCode,sampler2D channel) {
   return bool(texelFetch(channel, ivec2(keyCode,0), 0).x != 0.);
}

bool getKeyClick(int keyCode,sampler2D channel) {
   return bool(texelFetch(channel, ivec2(keyCode,1), 0).x != 0.);
}

//=============================================================
// cube related
//=============================================================

#define P +1.0
#define N -1.0  
const vec3[8] vertsBase = vec3[](
    vec3(N,N,N),vec3(N,N,P),vec3(P,N,P),vec3(P,N,N), 
    vec3(N,P,N),vec3(N,P,P),vec3(P,P,P),vec3(P,P,N));

const vec4 quads[6] = vec4[](vec4(0,1,2,3),vec4(7,6,5,4),vec4(3,7,4,0),vec4(2,1,5,6),vec4(4,5,1,0),vec4(6,7,3,2));

#define FACE_SOLID    1
#define FACE_TEXTURE1 2
#define FACE_TEXTURE2 3

struct FaceData {
    int kind;  
    float sz;  // texture region movement deltas, size
    vec2  uv;  // texture uv coordinate of UL corner of region
    vec3 color;
};

struct CubeData {
    vec3 pos;       // position
    vec3 rot;       // rotation
    float distance; // from camera
    float size;
    float range;    // 0 = no side shrinkage.  1 = shrunk to zero size
    bool isHighlighted;
    bool drawEdge;
    vec3 edgeColor;
    float edgeWidth;

    FaceData face[6];
};

//---------------------------------------------------------
void Line(vec2 pt, vec2 p1, vec2 p2, float thickness, vec3 color, inout vec3 O) {
  float a = distance(p1, pt);
  float b = distance(p2, pt);
  float c = distance(p1, p2);
  if ( a >= c || b >=  c ) return;

  float p = (a + b + c) * 0.5;
  float dist = 2.0 / c * sqrt( p * ( p - a) * ( p - b) * ( p - c));
  if (dist<thickness) O = color;
}

//---------------------------------------------------------
bool isLeft(vec2 a, vec2 b, vec2 c) {  // point c to the left of line a-b?
  return (b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x) < 0.;
}

//---------------------------------------------------------
float ptLineDistance(vec2 pt,vec2 lineP1,vec2 lineP2) {
    vec2 ab = lineP2-lineP1;
    vec2 be = pt-lineP2;     
    if(dot(ab,be) > 0.) return length(be);

    vec2 ae = pt-lineP1;
    if(dot(ab,ae) < 0.) return length(ae); 
    return abs(ab.x * ae.y - ab.y * ae.x) / length(ab);
}

vec3 normalVector(vec3 c,vec3 a,vec3 b) { return normalize(cross(b - a, c - a)); }

// ---------------------------------------------------------------------------------------

void cube(CubeData c,inout vec4 O, vec2 U,sampler2D txt1,sampler2D txt2) {
    float camDistance;
    vec3 verts[8];

    float offset = 1.;
    if(c.isHighlighted) offset = 1.5;    

    for (int i=0; i<8; i++) {           
        verts[i] = vertsBase[i];
        if(c.rot.x != 0.) verts[i].xz *= rotate(c.rot.x); 
        if(c.rot.y != 0.) verts[i].yz *= rotate(c.rot.y);  
        if(c.rot.z != 0.) verts[i].xy *= rotate(c.rot.z);  
        verts[i] -= c.pos * offset;
        rotateWorld(verts[i]);

        camDistance = distance(verts[i], camera);
        verts[i] *= c.size * (1.0 - camDistance * 0.01); // scale to size; ortho projection
        verts[i].xy += R * 0.5; // origin at screen center
    }

    vec3 edges[24];

    for (int i=0; i<6; i++) {
        vec3 center = (verts[int(quads[i].x)]+verts[int(quads[i].y)]+verts[int(quads[i].z)]+verts[int(quads[i].w)]) * 0.25;    
        for(int j=0;j<4;++j) 
            edges[i*4 + j] = verts[int(quads[i][j])] + ((center-verts[int(quads[i][j])]) * c.range);

        vec3 faceNormal = normalVector(edges[i*4 + 0],edges[i*4 + 2],edges[i*4 + 3]);
        if(dot(camera,faceNormal) > 0.) continue;  // backface culling

        int i4 = i*4;
        vec2 e0 = edges[i4 + 0].xy;
        vec2 e1 = edges[i4 + 1].xy;
        vec2 e2 = edges[i4 + 2].xy;
        vec2 e3 = edges[i4 + 3].xy;

        // is this face visible?
        bool inside = isLeft(e0,e1,U) && isLeft(e1,e2,U) && isLeft(e2,e3,U) && isLeft(e3,e0,U); 
        if(!inside) continue;

        // fill interior of face
        if(c.face[i].kind == FACE_SOLID) 
            O.xyz = c.face[i].color;
        else {
            vec2 tuv = U;

            float dx1 = ptLineDistance(U,e0,e1);
            float dx2 = ptLineDistance(U,e2,e3);
            tuv.x = dx1/(dx1+dx2);

            float dy1 = ptLineDistance(U,e0,e3);
            float dy2 = ptLineDistance(U,e1,e2);
            tuv.y = dy1/(dy1+dy2);

            // tuv 0...1;  now adjust for specifed region
            tuv = c.face[i].uv + tuv * c.face[i].sz; 
            tuv = fract(1.0 + tuv); // wrap around

            vec3 q;
            if(c.face[i].kind == FACE_TEXTURE1) {
                tuv *= vec2(textureSize(txt1,0));
                q = texelFetch(txt1,ivec2(tuv),0).xyz;
            }
            else {
                tuv *= vec2(textureSize(txt2,0));
                q = texelFetch(txt2,ivec2(tuv),0).xyz;
            }

            // for static textures
           // O.xyz = q;

            // for Claude video
            const float s = 1.5;
            if(q.z < q.x*s && q.z < q.y*s) O.xyz = q;
        }

        // edges 
        if(c.drawEdge) {
            Line(U,e0,e1, c.edgeWidth, c.edgeColor, O.xyz);  
            Line(U,e1,e2, c.edgeWidth, c.edgeColor, O.xyz);  
            Line(U,e2,e3, c.edgeWidth, c.edgeColor, O.xyz);  
            Line(U,e3,e0, c.edgeWidth, c.edgeColor, O.xyz);
        }
    }
}

int oldRand;
int iRandom(int max) {
    oldRand += max + max/3;
    return oldRand % max;
}

void resetGame() {
    qWorld = vec2(0.);
    qHighlight1 = FEMPTY;
    qHighlight2 = FEMPTY;

    oldRand = (iFrame + int(iTime)) % NUMCUBE;
    for(int i=0;i<NUMCUBE;++i) 
        setCubeEntry(i,(i*3+oldRand) % NUMREGION);
}     

void mainImage(out vec4 O, vec2 U) {
    if(U.x > float(QSIZE) || U.y > 1.0) return; 
    R = iResolution.xy;

    if(iFrame < 2 || getKeyState(82,iChannel3)) {
        resetGame();
        saveData(O,U);
        return;
    }

    loadData(iChannel0);

    if(U.x < 1. && U.y < 1.) { // qWorld
        if(sign(iMouse.w) > 0.) { // button is clicked.  determine which cube they selected
            cubeSize = iResolution.x * 0.06;

            float d,bestDistance = 0.;
            int bestIndex = -1;       
            vec3 pos;
            for(int i=0;i<NUMCUBE;++i) {
                if(getCubeEntry(i) == EMPTY) continue;
                pos = finalPosition(i, (i == int(qHighlight1) || i == int(qHighlight2)));

                if(distance(pos.xy,iMouse.xy) > cubeSize * 0.7) continue;

                d = distance(pos, camera);
                if(d > bestDistance) {
                    bestDistance = d;
                    bestIndex = i;
                 }
            }

            if(bestIndex >= 0) {         // cube was selected
                float bi = float(bestIndex);
                  if(qHighlight1 == bi)   // toggle selection back off
                    qHighlight1 = FEMPTY;
                else
                if(qHighlight2 == bi) 
                    qHighlight2 = FEMPTY;
                else                    
                if(qHighlight1 == FEMPTY) // store selection
                    qHighlight1 = bi;
                else
                if(qHighlight2 == FEMPTY) 
                    qHighlight2 = bi;
           }

        }
        else if(sign(iMouse.z) > 0.) {  // mouse drag: spin world
            qWorld += (iMouse.xy - abs(iMouse.zw)) * 0.001;
        }

        qWorld.x += 0.001;   // auto world spin
        qWorld.y += 0.0012;
    }

    if(getKeyState(32,iChannel3)) { // <Space>
        int c1 = int(qHighlight1);
        int c2 = int(qHighlight2);

        if(c1 != EMPTY && c2 != EMPTY) {  // matching cubes?
            if(getCubeEntry(c1) == getCubeEntry(c2)) {
                setCubeEntry(c1,EMPTY);
                setCubeEntry(c2,EMPTY);
            }        
        }

        qHighlight1 = FEMPTY; // in any case, reset the selections
        qHighlight2 = FEMPTY;
    }


    saveData(O,U);
}
